contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount);
        uint balBefore = address(this).balance;
        uint potBefore = c.pot(); if (__ESBMC_reverted()) return;
        bool reverted;
        c.play{value: amount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
        uint balAfter = address(this).balance;
        uint potAfter = c.pot(); if (__ESBMC_reverted()) return;
        assert(
            (reverted && potAfter == potBefore && balAfter == balBefore) ||
            (!reverted && amount == 10 &&
                ((potAfter == potBefore + 10) ||
                 (potAfter == 0 && balAfter >= potBefore)))
        );
    }
    receive() external payable {}
}

